<?php

declare(strict_types=1);
require __DIR__ . '/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Core\TenantFeatures;
use EventMenu\Services\PublicMenuService;

$pdo=Database::connection();$slug=trim((string)($_GET['empresa']??''));$stmt=$pdo->prepare('SELECT * FROM tenants WHERE slug=? AND status="active" LIMIT 1');$stmt->execute([$slug]);$tenant=$stmt->fetch();if(!$tenant){http_response_code(404);exit('Empresa não encontrada.');}$tenantId=(int)$tenant['id'];if(!TenantFeatures::menu($tenantId)){http_response_code(404);exit('Cardápio não habilitado para esta empresa.');}$settings=json_decode((string)($tenant['settings']??'{}'),true)?:[];
$tableToken=trim((string)($_GET['mesa']??''));$table=null;if($tableToken!==''){$s=$pdo->prepare('SELECT * FROM restaurant_tables WHERE tenant_id=? AND qr_token=? AND status<>"inactive" LIMIT 1');$s->execute([$tenantId,$tableToken]);$table=$s->fetch()?:null;if(!$table){http_response_code(404);exit('Mesa não encontrada ou inativa.');}}
$cartKey='public_cart_'.$tenantId;if(!isset($_SESSION[$cartKey])||!is_array($_SESSION[$cartKey]))$_SESSION[$cartKey]=[];$cart=&$_SESSION[$cartKey];$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada. Atualize a página.';else{
        $action=(string)($_POST['action']??'');
        if($action==='add'){$id=(int)($_POST['product_id']??0);$qty=max(1,min(99,(int)($_POST['qty']??1)));$s=$pdo->prepare('SELECT id,name,price_cents,track_stock,stock_qty FROM products WHERE id=? AND tenant_id=? AND active=1');$s->execute([$id,$tenantId]);$p=$s->fetch();if(!$p)$error='Produto indisponível.';elseif((int)$p['track_stock']&&(float)$p['stock_qty']<=0)$error='Produto sem estoque.';else{$cart[$id]=($cart[$id]??0)+$qty;}}
        elseif($action==='remove'){unset($cart[(int)($_POST['product_id']??0)]);}
        elseif($action==='clear'){$cart=[];}
        elseif($action==='checkout'){
            try{$rows=[];foreach($cart as $productId=>$qty)$rows[]=['product_id'=>(int)$productId,'qty'=>(float)$qty];$order=(new PublicMenuService())->create($tenantId,$rows,(string)($_POST['name']??''),(string)($_POST['phone']??''),(string)($_POST['address']??''),$table?$tableToken:null);$cart=[];header('Location: '.app_url('pedido.php?t='.rawurlencode($order['public_token'])),true,303);exit;}catch(Throwable $e){$error=$e->getMessage();}
        }
        if($action!=='checkout'&&$error===null){$query=['empresa'=>$slug];if($table)$query['mesa']=$tableToken;header('Location: '.app_url('menu.php?'.http_build_query($query)),true,303);exit;}
    }
}
$c=$pdo->prepare('SELECT * FROM categories WHERE tenant_id=? AND active=1 ORDER BY sort_order,name');$c->execute([$tenantId]);$categories=$c->fetchAll();$p=$pdo->prepare('SELECT * FROM products WHERE tenant_id=? AND active=1 ORDER BY category_id,name');$p->execute([$tenantId]);$products=$p->fetchAll();$productMap=[];foreach($products as $prod)$productMap[(int)$prod['id']]=$prod;$cartRows=[];$cartTotal=0;foreach($cart as $id=>$qty){$prod=$productMap[(int)$id]??null;if(!$prod)continue;$line=(int)$prod['price_cents']*(int)$qty;$cartTotal+=$line;$cartRows[]=['id'=>(int)$id,'name'=>$prod['name'],'qty'=>(int)$qty,'line'=>$line];}
function m(int $c):string{return 'R$ '.number_format($c/100,2,',','.');}
$deliveryFee=max(0,(int)($settings['delivery_fee_cents']??0));$minimum=max(0,(int)($settings['min_delivery_order_cents']??0));
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0b0f14"><title><?= Security::e($tenant['name']) ?> — Cardápio</title><link rel="stylesheet" href="<?= Security::e(app_url('assets/app.css')) ?>"><style>.menu-shell{max-width:1160px;margin:auto;padding:28px 18px}.hero{padding:30px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(135deg,#181e2a,#11151d);margin-bottom:22px}.menu-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,1fr);gap:18px}.product{display:grid;grid-template-columns:72px 1fr auto;gap:16px;align-items:center}.product+.product{border-top:1px solid var(--line);margin-top:14px;padding-top:14px}.product-image{width:72px;height:72px;border-radius:14px;object-fit:cover;background:#151a22}.cart{position:sticky;top:18px}.price{font-weight:800;color:var(--accent)}@media(max-width:800px){.menu-grid{grid-template-columns:1fr}.cart{position:static}.product{grid-template-columns:1fr auto}.product-image{display:none}}</style></head><body><main class="menu-shell"><section class="hero"><div class="brand">EventMenu <span>Premium</span></div><h1><?= Security::e($tenant['name']) ?></h1><?php if($table):?><p><span class="badge">Pedido na <?= Security::e($table['name']) ?></span></p><p class="muted">Os pedidos deste QR ficam ligados à mesa/comanda automaticamente.</p><?php else:?><p class="muted">Cardápio digital · delivery · pagamento online</p><?php if($minimum>0):?><p class="muted">Pedido mínimo: <?= m($minimum) ?><?= $deliveryFee>0?' · Taxa padrão: '.m($deliveryFee):'' ?></p><?php endif;?><?php endif;?><?php if(!empty($settings['menu_message'])):?><p><?= Security::e((string)$settings['menu_message']) ?></p><?php endif;?></section><?php if($error):?><div class="alert error"><?= Security::e($error) ?></div><?php endif;?><div class="menu-grid"><section><?php foreach($categories as $cat):?><div class="card" style="margin-bottom:16px"><div class="section-head"><h2><?= Security::e($cat['name']) ?></h2></div><?php foreach($products as $prod):if((int)$prod['category_id']!==(int)$cat['id'])continue;$out=(int)$prod['track_stock']&&(float)$prod['stock_qty']<=0;?><div class="product"><?php if($prod['image_url']):?><img class="product-image" src="<?= Security::e($prod['image_url']) ?>" alt=""><?php else:?><div class="product-image"></div><?php endif;?><div><strong><?= Security::e($prod['name']) ?></strong><div class="muted"><?= Security::e($prod['description']??'') ?></div><div class="price"><?= m((int)$prod['price_cents']) ?></div><?php if($out):?><span class="badge">Esgotado</span><?php endif;?></div><form method="post" class="actions"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= (int)$prod['id'] ?>"><input type="number" name="qty" min="1" max="99" value="1" style="width:64px"<?= $out?' disabled':'' ?>><button class="primary"<?= $out?' disabled':'' ?>>Adicionar</button></form></div><?php endforeach;?></div><?php endforeach;?></section><aside class="card cart"><div class="section-head"><h2><?= $table?'Pedido da mesa':'Seu pedido' ?></h2><?php if($cartRows):?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="clear"><button class="secondary">Limpar</button></form><?php endif;?></div><?php if(!$cartRows):?><p class="muted">Seu carrinho está vazio.</p><?php else:?><?php foreach($cartRows as $i):?><div class="section-head"><span><?= (int)$i['qty'] ?>× <?= Security::e($i['name']) ?><br><strong><?= m($i['line']) ?></strong></span><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= (int)$i['id'] ?>"><button class="secondary">×</button></form></div><?php endforeach;?><hr style="border-color:var(--line)"><p><strong>Subtotal <span style="float:right"><?= m($cartTotal) ?></span></strong></p><?php if(!$table&&$deliveryFee>0):?><p class="muted">Taxa de entrega: <?= m($deliveryFee) ?></p><?php endif;?><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="checkout"><label class="span-2">Nome<input name="name" required></label><label class="span-2">Telefone<input name="phone"<?= $table?'':' required' ?>></label><?php if(!$table):?><label class="span-2">Endereço<textarea name="address" required></textarea></label><?php else:?><div class="span-2 muted">Mesa: <?= Security::e($table['name']) ?></div><?php endif;?><button class="primary span-2">Continuar para pagamento</button></form><?php endif;?></aside></div></main></body></html>
